/* PRINT SIZES. The page prints at 0.734 zoom and step15 fails anything
   under 11px printed, so a label may not go below 15px here. `.72em` of a
   19px display line is 13.7px = 10.1px printed, which is under the floor —
   so the labels are set in absolute px from the page scale instead of
   inheriting a fraction of whatever they sit inside. */
.subj-chemistry .rxn>.rxn-t, .subj-chemistry .rxn>.rxn-b { font-size:15px; }
.subj-chemistry .acol .rxn>.rxn-t, .subj-chemistry .acol .rxn>.rxn-b { font-size:15px; }

/* A reaction line is the widest thing chemistry sets. Given the room of
   a full column it reads; cramped it does not, so it is given the display
   line's full measure and allowed to wrap between species. */
.subj-chemistry .dm { font-size:18px; line-height:2.05; }
.subj-chemistry .acol .dm { font-size:17px; line-height:2.0; }
.subj-chemistry .rxn { min-width:52px; margin:0 7px; }
.subj-chemistry .acol .rxn { min-width:44px; margin:0 5px; }

/* ONE STARTING LINE, AND THE EQUATION IS A UNIT.
   Centred display equations gave every reaction a different left
   edge, so `(iv)`, its equation and the sentence under it each
   began somewhere else and the eye had no line to follow. Left
   aligned at a single indent, the answer reads down one column:
   enumerator, equation, comment.
   The indent is a rule, not a margin, so the equation is visibly
   one object — a mini diagram — rather than another paragraph. */
.subj-chemistry .dm { text-align:left; margin:13px 0 13px 0;
     padding:3px 0 3px 14px; border-left:2px solid #dfe4ee; }
.subj-chemistry .acol .dm { padding-left:11px; }
/* TWELVE EQUATIONS SAT FLUSH TO THE COLUMN EDGE.
   Measured in Chrome at the built page: none was clipped, but each
   ended exactly on the column's right edge with no margin, which
   reads as cramped and is one rounding error away from being cut.
   Half a point off the column display size buys about 3% of width
   and still prints at 12.1px, well clear of the 11px floor. */
.subj-chemistry .acol .dm { font-size:16.5px; }

/* ARROWS ALL THE SAME LENGTH unless a label forces otherwise.
   Arrow width came only from `min-width`, so an unlabelled arrow
   was 44px, `पिरिडीन` made one 90px and a two-line condition made
   another 150px — three different arrows in one answer, which is
   what made the reagent labels look like they were floating
   rather than attached. A common floor of 74px puts most of them
   at the same length; only a genuinely long condition exceeds it. */
.subj-chemistry .rxn { min-width:74px; margin:0 8px; }
.subj-chemistry .acol .rxn { min-width:66px; margin:0 7px; }
/* A reaction never breaks apart. It may wrap between species, and
   never inside one or between an arrow and its labels. */
.subj-chemistry .rxn, .subj-chemistry .sp { break-inside:avoid; }
.subj-chemistry .dm { overflow-wrap:normal; }

/* The atom row is the baseline row — see `base.rules` for why.
   This slot previously pushed the whole stack DOWN by 0.62em to
   compensate for the grid taking its baseline from the number
   above the atom; with the rows reordered that compensation is
   itself the misalignment. */
.subj-chemistry .sp>.sp-c { line-height:1.18; }

/* POINT 5 — A HIERARCHY AFTER `उत्तर:`.
   Main answer, explanation, textbook note, equation and caption were all
   one weight and one size, so a long answer read as a single stream. Four
   levels, each a small step down from the one above: the answer carries
   the page's prose size, an explanation drops half a point and loses a
   little contrast, and a caption is smaller again and italic. */
.subj-chemistry .anstext { font-size:17px; line-height:1.66; }
.subj-chemistry .anstext+p.q, .subj-chemistry .ansrow~p.q
   { font-size:16.5px; color:#3d4351; }
.subj-chemistry .anssub { font-size:16px; letter-spacing:.1px; }

/* POINT 6 — A RESERVED PLATE, NOT AN EMPTY BOX.
   56 of chapter 6's 79 structure files are not on disk, so most figures
   are placeholders — and a 2.5px dashed blue border round a tinted
   158px rectangle is heavier than the answer it interrupts. Three of
   them on a page is most of what read as unused white space.
   A hairline, no fill, a smaller reserved area and the caption directly
   underneath: it holds the space without claiming the eye. */
.subj-chemistry .figcard { border:1px dashed #c3cddd; background:none;
     border-radius:8px; padding:7px 11px; margin:10px 0; }
.subj-chemistry .figcard>.fh { font-size:14.5px; font-weight:600;
     color:#7b8699; margin-bottom:3px; gap:6px; }
.subj-chemistry .figcard>.figspace { height:96px !important;
     border:0; background:none; }
.subj-chemistry .figcard>.fd { font-size:15px; line-height:1.5;
     color:#5b6474; font-style:italic; margin-top:4px; }

/* POINT 7 — FEWER VOICES.
   Hindi prose, chemical notation, subscripts, arrow labels and captions
   each had their own size and weight, so nothing was clearly primary.
   Notation now shares the prose size and weight and differs only by
   being upright and serif; labels and captions share ONE small size. */
.subj-chemistry .m { font-size:1em; font-weight:400; }
.subj-chemistry .rxn>.rxn-t, .subj-chemistry .rxn>.rxn-b,
.subj-chemistry .sp>.sp-u, .subj-chemistry .figcard>.fh
   { font-size:15px; font-weight:400; }
.subj-chemistry sub, .subj-chemistry sup { font-weight:400; }

/* POINT 3 — WHITESPACE ON PURPOSE.
   The complaint was rhythm, not quantity: dense, dense, then a large
   empty region. A band above every question and a fixed band around
   every equation give the column a repeating beat, so the space that is
   left reads as a rest rather than as a gap where something failed to
   fit. */
.subj-chemistry .qhead { margin-top:15px; }
.subj-chemistry .ansrow { margin-top:9px; }
.subj-chemistry .figcard { margin:13px 0; }
.subj-chemistry p.q+.dm, .subj-chemistry .anstext+.dm { margin-top:9px; }
